"use strict";
function parseLog(text) {
  const rows = String(text)
    .split("\n")
    .filter(Boolean)
    .map((line) => {
      const [at, level, user, ...rest] = line.split(" ");
      return { at: Number(at), level: level, user: user === "-" ? undefined : user, message: rest.join(" ") };
    });
  // Entries travel as JSON (the log format's own wire form).
  return JSON.parse(JSON.stringify(rows));
}
function summarize(entries) {
  return { count: entries.length, last: entries.length === 0 ? undefined : entries[entries.length - 1].message };
}
exports.parseLog = parseLog;
exports.summarize = summarize;
